/**
 * ActionList — acciones de una fila abiertas desde MoreButton (Mi Garaje, /blocks/mi-garaje/m/vmc · Mis publicaciones). Tarjeta
 * blanca dentro de la misma fila, a todo el ancho: un renglón por acción con su ícono y una flecha («Dar de baja», en rojo,
 * con el tacho). Una acción sin ícono va como ProfileButton («Ver detalle de la venta»). Esc la cierra.
 * Depende de React y ProfileButton.
 */
import type { JSX, KeyboardEvent } from "react";
import ProfileButton from "@/concorde/components/ProfileButton";

export const ACTION_LIST_CSS = String.raw`
.mp-acts { display:grid; align-items:center; gap:0; padding:4px; border-radius:12px; background:#fff; box-shadow:inset 0 0 0 1px #ECE8F7; animation:mp-acts-in .2s cubic-bezier(.2,.8,.2,1); font-family:var(--vmc-font-display); }
@keyframes mp-acts-in { from { opacity:0; transform:translateY(-6px); } }
.mp-acts svg { flex:none; width:16px; height:16px; }
.mp-acts button { font-family:inherit; line-height:1.2; cursor:pointer; }
.mp-acts button:focus-visible { outline:2px solid #8460E5; outline-offset:2px; }
.mp-acts__go, .mp-acts__danger { display:inline-flex; align-items:center; gap:6px; width:100%; min-height:44px; padding:0 12px; border:0; border-radius:8px; background:none; font-size:14px; font-weight:600; transition:background-color .15s, transform .15s; }
.mp-acts__go { color:#3B1782; } .mp-acts__danger { color:#B42318; }
.mp-acts :is(.mp-acts__go, .mp-acts__danger):hover { background:#F6F4FB; }
.mp-acts button + button { box-shadow:0 -1px 0 #F0EDF8; }
.mp-acts__chev { margin-left:auto; color:#B3A8DA; }
@media (prefers-reduced-motion:reduce) { .mp-acts { animation:none; } .mp-acts button { transition:none; } }
`;

/** Una acción de la lista. */
export interface ActionListItem {
  /** Texto (p. ej. «Dar de baja»). */
  label: string;
  /** Ícono: el tacho. Sin ícono, la acción va como ProfileButton. */
  icon?: "trash";
  /** Acción destructiva: en rojo. */
  danger?: boolean;
}

export interface ActionListProps {
  /** id de la lista (lo usa aria-controls de MoreButton). */
  id: string;
  /** Nombre accesible (p. ej. «Acciones: Toyota Etios 2020»). */
  label: string;
  /** Acciones, en orden. */
  items: ActionListItem[];
  /** Al elegir una acción (recibe su índice). */
  onPick: (index: number) => void;
  /** Esc dentro de la lista. */
  onClose: () => void;
}

const PATH = { trash: "M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3" } as const;

export function ActionList({ id, label, items, onPick, onClose }: ActionListProps): JSX.Element {
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => { if (e.key === "Escape") onClose(); };
  return <>
    <style href="concorde-action-list" precedence="default">{ACTION_LIST_CSS}</style>
    <div id={id} className="mp-acts" role="group" aria-label={label} onKeyDown={onKeyDown}>
      {items.map((a, i) => !a.icon ? <ProfileButton key={a.label} onClick={() => onPick(i)}>{a.label}</ProfileButton>
        : <button key={a.label} type="button" className={a.danger ? "mp-acts__danger" : "mp-acts__go"} autoFocus={i === 0} onClick={() => onPick(i)}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden><path d={PATH[a.icon]} /></svg>{a.label}
          <svg className="mp-acts__chev" width="16" height="16" viewBox="0 0 20 20" aria-hidden><path d="M8 5l5 5-5 5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg></button>)}
    </div>
  </>;
}

export default ActionList;

"use client";

/**
 * ProfileButton — Generado por Concorde
 * Fuente: Figma VOYAGER · "ProfileButton" (Status=Default|Hover|Pressed)
 * Nodos: 1274:5029 (default) · 1274:3989 (hover) · 1287:5144 (pressed)
 * Sincronizado: 2026-06-12
 *
 * Botón de navegación a perfil: label morado + círculo con chevron.
 * Figma manda en lo visual (colores/dimensiones); Concorde manda en la interacción
 * (transición de relleno + lift en hover, reduced-motion).
 */

import type { JSX, MouseEventHandler, ReactNode } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ProfileButtonProps {
  /** Label (default: "Ir al Perfil") */
  children?: ReactNode;
  /** Si se pasa, renderiza un <a> en vez de <button> */
  href?: string;
  onClick?: MouseEventHandler<HTMLElement>;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

// ─── Self-contained CSS ───────────────────────────────────────────────────────

const STYLE_ID = "concorde-profilebutton-styles";

const PROFILEBUTTON_STYLES = `
.pprofilebtn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 4px;
  background: none;
  border: none;
  cursor: pointer;
  text-decoration: none;
  font-family: var(--vmc-font-display, "Plus Jakarta Sans", -apple-system, sans-serif);
  font-size: 15px;
  font-weight: 600;
  line-height: 20px;
  white-space: nowrap;
  -webkit-tap-highlight-color: transparent;
}

/* Label — default morado #3B1782 (Figma text fill) */
.pprofilebtn__label {
  color: #3b1782;
  transition: color 0.2s ease;
}

/* Círculo 16px con chevron. color = color del chevron (currentColor) */
.pprofilebtn__circle {
  position: relative;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  border-radius: 9999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  color: #ed8936;
  transition:
    background 0.2s ease,
    color 0.2s ease,
    box-shadow 0.25s ease,
    transform 0.2s cubic-bezier(0.25, 0.8, 0.25, 1);
}
/* Default: anillo gradiente naranja 1.5px (stroke #F4AC59 → #ED8936 40% → #B25614) — mask */
.pprofilebtn__circle::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1.5px;
  background: linear-gradient(135deg, #f4ac59 0%, #ed8936 40%, #b25614 100%);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  transition: opacity 0.2s ease;
}
.pprofilebtn__chevron {
  position: relative;
  z-index: 1;
  display: block;
}

/* ── Hover: círculo RELLENO naranja + sombra, chevron blanco, lift ── */
.pprofilebtn:hover:not(:disabled) .pprofilebtn__circle {
  background: linear-gradient(90deg, #f4ac59 0%, #ed8936 40%, #b25614 100%);
  color: #ffffff;
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
  transform: translateY(-1px);
}
.pprofilebtn:hover:not(:disabled) .pprofilebtn__circle::before { opacity: 0; }

/* ── Pressed: texto + chevron gris #99A1AF, círculo naranja oscuro #B25614 → #93420A ── */
.pprofilebtn:active:not(:disabled) .pprofilebtn__label { color: #99a1af; }
.pprofilebtn:active:not(:disabled) .pprofilebtn__circle {
  background: linear-gradient(90deg, #b25614 0%, #93420a 100%);
  color: #99a1af;
  box-shadow: none;
  transform: translateY(0);
}
.pprofilebtn:active:not(:disabled) .pprofilebtn__circle::before { opacity: 0; }

/* ── Focus ── */
.pprofilebtn:focus-visible {
  outline: none;
  border-radius: 8px;
  box-shadow: 0 0 0 2px #ffffff, 0 0 0 4px #8460e5;
}

/* ── Disabled ── */
.pprofilebtn:disabled {
  cursor: not-allowed;
}
.pprofilebtn:disabled .pprofilebtn__label { color: #99a1af; }
.pprofilebtn:disabled .pprofilebtn__circle {
  background: #e1e3e2;
  color: #ffffff;
}
.pprofilebtn:disabled .pprofilebtn__circle::before { opacity: 0; }

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  .pprofilebtn__label,
  .pprofilebtn__circle,
  .pprofilebtn__circle::before { transition: none; }
  .pprofilebtn:hover:not(:disabled) .pprofilebtn__circle { transform: none; }
}
`;

let _stylesInjected = false;

// ─── Chevron (M83 22 L87 19 L83 16 normalizado a viewBox 16×16, centro 8,8) ─────

function Chevron(): JSX.Element {
  return (
    <svg
      className="pprofilebtn__chevron"
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
    >
      <path d="M6 11L10 8L6 5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

// ─── Component ────────────────────────────────────────────────────────────────

export default function ProfileButton({
  children = "Ir al Perfil",
  href,
  onClick,
  disabled = false,
  className = "",
  "aria-label": ariaLabel,
}: ProfileButtonProps): JSX.Element {
  if (typeof document !== "undefined" && !_stylesInjected) {
    if (!document.getElementById(STYLE_ID)) {
      const el = document.createElement("style");
      el.id = STYLE_ID;
      el.textContent = PROFILEBUTTON_STYLES;
      document.head.appendChild(el);
    }
    _stylesInjected = true;
  }

  const classes = ["pprofilebtn", className].filter(Boolean).join(" ");

  const inner = (
    <>
      <span className="pprofilebtn__label">{children}</span>
      <span className="pprofilebtn__circle" aria-hidden="true">
        <Chevron />
      </span>
    </>
  );

  return (
    <>
      <style id={`${STYLE_ID}-ssr`} suppressHydrationWarning dangerouslySetInnerHTML={{ __html: PROFILEBUTTON_STYLES }} />
      {href && !disabled ? (
        <a className={classes} href={href} onClick={onClick} aria-label={ariaLabel}>
          {inner}
        </a>
      ) : (
        <button type="button" className={classes} onClick={onClick} disabled={disabled} aria-label={ariaLabel}>
          {inner}
        </button>
      )}
    </>
  );
}
